function hypot(a, b){ return Math.sqrt(a*a + b*b); }
function leg(c, a){ var v=c*c - a*a; return v>0 ? Math.sqrt(v) : NaN; }
function isRight(a, b, c){ var s=[a,b,c].sort(function(x,y){return x-y;}); return Math.abs(s[0]*s[0]+s[1]*s[1]-s[2]*s[2]) < 1e-9; }
var EXPORTS = { hypot:hypot, leg:leg, isRight:isRight };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PythagoreanForgePure = EXPORTS; }
